// SMS gate for US customers. Pure and synchronous: it never sends and keeps no state.
// Rule sources: TCPA, 47 CFR 64.1200 (a)(2) consent, (a)(10) revocation, (c)(1) calling hours;
// CTIA Messaging Principles and Best Practices (consent, opt-out, STOP notice).

const SOLICIT_START_MIN = 8 * 60; // 08:00 local, included
const SOLICIT_END_MIN = 21 * 60; // 21:00 local, excluded (rule: not "after 9 p.m.")

const E164_US = /^\+1[2-9]\d{2}[2-9]\d{6}$/;
const STOP_NOTICE = /\bSTOP\b/i;

const block = (reason) => ({ allowed: false, reason });

function localMinutes(now, timeZone) {
  try {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone,
      hourCycle: "h23",
      hour: "numeric",
      minute: "numeric",
    }).formatToParts(now);
    const h = Number(parts.find((p) => p.type === "hour").value);
    const m = Number(parts.find((p) => p.type === "minute").value);
    return h * 60 + m;
  } catch {
    return null; // invalid or missing IANA zone
  }
}

export function checkSms(message, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) return block("invalid_now");
  if (!message || typeof message !== "object") return block("invalid_message");
  const { kind, body, to } = message;
  if (kind !== "marketing" && kind !== "transactional") return block("invalid_kind");
  if (typeof body !== "string" || body.trim() === "") return block("empty_body");
  if (!to || typeof to !== "object") return block("invalid_recipient");
  if (typeof to.phone !== "string" || !E164_US.test(to.phone)) return block("invalid_us_phone");

  // Transactional texts: customer triggered them, so consent, opt-out and calling hours
  // for solicitations do not apply (a marketing STOP does not stop a login code).
  if (kind === "transactional") return { allowed: true, reason: null };

  // Marketing below. Any unknown value blocks (fail closed).
  // 1. Revocation: any non-null optedOutAt blocks, valid date or not, past or future.
  if (to.optedOutAt !== null && to.optedOutAt !== undefined) {
    return block(Number.isNaN(Date.parse(to.optedOutAt)) ? "invalid_opt_out_date" : "opted_out");
  }
  // 2. Prior express written consent: only an explicit true counts.
  if (to.marketingConsent !== true) return block("no_marketing_consent");
  // 3. Calling hours at the recipient's location, 8:00 up to but not including 21:00.
  const minutes = localMinutes(now, to.timeZone);
  if (minutes === null) return block("invalid_time_zone");
  if (minutes < SOLICIT_START_MIN || minutes >= SOLICIT_END_MIN) return block("quiet_hours");
  // 4. CTIA: marketing text must tell the customer how to opt out.
  if (!STOP_NOTICE.test(body)) return block("missing_opt_out_notice");

  return { allowed: true, reason: null };
}

import assert from "node:assert/strict";
import { checkSms } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/ours-g1-1/bot.mjs";
const to = (o = {}) => ({ phone: "+13125550142", timeZone: "America/Chicago", marketingConsent: true, optedOutAt: null, ...o });
const m = (kind, o, body = "Sale today! Reply STOP to opt out") => ({ kind, body, to: to(o) });
const t = (s) => new Date(s);
const r = (msg, d) => checkSms(msg, t(d)).reason;
// Chicago CDT = UTC-5 in October, CST = UTC-6 in January
assert.deepEqual(checkSms(m("marketing"), t("2026-10-22T17:00:00Z")), { allowed: true, reason: null });
assert.equal(r(m("marketing"), "2026-10-22T12:59:00Z"), "quiet_hours"); // 07:59
assert.equal(r(m("marketing"), "2026-10-22T13:00:00Z"), null); // 08:00
assert.equal(r(m("marketing"), "2026-10-23T01:59:00Z"), null); // 20:59
assert.equal(r(m("marketing"), "2026-10-23T02:00:00Z"), "quiet_hours"); // 21:00
assert.equal(r(m("marketing"), "2026-01-22T13:59:00Z"), "quiet_hours"); // 07:59 CST
assert.equal(r(m("marketing"), "2026-01-22T14:00:00Z"), null); // 08:00 CST
assert.equal(r(m("marketing", { timeZone: "Pacific/Honolulu" }), "2026-10-22T17:00:00Z"), "quiet_hours"); // 07:00
assert.equal(r(m("marketing", { timeZone: "Nope/Zone" }), "2026-10-22T17:00:00Z"), "invalid_time_zone");
assert.equal(r(m("marketing", { marketingConsent: false }), "2026-10-22T17:00:00Z"), "no_marketing_consent");
assert.equal(r(m("marketing", { marketingConsent: undefined }), "2026-10-22T17:00:00Z"), "no_marketing_consent");
assert.equal(r(m("marketing", { optedOutAt: "2026-10-01T00:00:00Z" }), "2026-10-22T17:00:00Z"), "opted_out");
assert.equal(r(m("marketing", { optedOutAt: "garbage" }), "2026-10-22T17:00:00Z"), "invalid_opt_out_date");
assert.equal(r(m("marketing", {}, "Big sale"), "2026-10-22T17:00:00Z"), "missing_opt_out_notice");
assert.equal(r(m("marketing", { phone: "12345" }), "2026-10-22T17:00:00Z"), "invalid_us_phone");
// transactional: night, no consent, opted out -> still allowed
assert.equal(r(m("transactional", { marketingConsent: false, optedOutAt: "2026-10-01T00:00:00Z" }, "Code 123456"), "2026-10-22T08:00:00Z"), null);
assert.equal(r({ kind: "x", body: "a", to: to() }, "2026-10-22T17:00:00Z"), "invalid_kind");
assert.equal(checkSms(m("marketing"), new Date("bad")).reason, "invalid_now");
console.log("ok");
